function geometryPointerMove(e){var canvas=e.target.closest('#geomCanvas');if(!canvas)return;var p=geometryCanvasPoint(e,canvas);geomHover=p;if(geomTool==='compass'&&geomCompass.pivot&&geomCompass.radius!==null){geomCompass.tip=compassProjectedPoint(p);if(geomCompass.dragging&&geomCompass.penDown&&geomDrawingIndex>=0){var arc=geomObjects[geomDrawingIndex];if(arc&&arc.type==='compassArc'){var lastPt=arc.pts[arc.pts.length-1];if(!lastPt||Math.hypot(p.x-lastPt.x,p.y-lastPt.y)>2)arc.pts.push(geomCompass.tip);}}drawGeometry();e.preventDefault();return;}if(geomDrawing&&geomDrawingIndex>=0){var o=geomObjects[geomDrawingIndex];if(o&&o.type==='pencil')o.pts.push(p);}drawGeometry();}
